import type { VisualKind } from './summary-lessons'
import type { VisualTheorem } from './summary-theorems'

const b=(id:string,en:string)=>({id,en})
function concept(kind:string,mode:string,titleId:string,titleEn:string,id:string,en:string,whyId:string,whyEn:string,conditionId:string,conditionEn:string,tex:string,exampleId:string,exampleEn:string):VisualTheorem {
  return {scene:'supplement',diagram:{kind,mode},title:b(titleId,titleEn),statement:b(id,en),why:b(whyId,whyEn),conditions:b(conditionId,conditionEn),tex,caption:b(exampleId,exampleEn)}
}

/** Each group fills the additional definitions and results inside its syllabus entry. */
export const SUMMARY_CONCEPTS: Record<VisualKind,VisualTheorem[]> = {
  triangle:[
    concept('complexArithmetic','product','Perkalian kompleks','Complex multiplication','Perkalian mencampur dua koordinat, tetapi tetap dapat dibaca sebagai skala dan rotasi.','Multiplication mixes the two coordinates, but can be read as scaling and rotation.','Kembangkan (a+bi)(c+di), lalu ganti i² dengan −1. Bagian real menjadi ac−bd dan bagian imajiner ad+bc.','Expand (a+bi)(c+di), then replace i² with −1. The real part is ac−bd and the imaginary part ad+bc.','a,b,c,d real. Panjang hasil adalah hasil kali panjang kedua masukan.','a,b,c,d are real. The product length is the product of the input lengths.',String.raw`(a+bi)(c+di)=(ac-bd)+i(ad+bc)`,'Contoh: kalikan z = 1+i dengan 2+i. Dua panah masukan menghasilkan panah 1+3i; garis bantu menunjukkan komponen.','Example: multiply z = 1+i by 2+i. The input arrows produce 1+3i; guide lines show the components.'),
    concept('complexArithmetic','division','Pembagian dan konjugat','Division and conjugation','Membagi oleh w membatalkan skala dan rotasi yang dibuat oleh w.','Dividing by w undoes the scaling and rotation made by w.','Kalikan pembilang dan penyebut dengan konjugat w. Penyebut w w̄ menjadi |w|² yang real; kini pembagian dilakukan per koordinat.','Multiply numerator and denominator by the conjugate of w. The denominator w w̄ becomes the real |w|²; divide each coordinate by it.','w ≠ 0. Konjugasi tidak membuat pembagian oleh nol sah.','w ≠ 0. Conjugation does not make division by zero valid.',String.raw`z/w=z\bar w/|w|^2`,'Contoh awal (1+i)/(2+i) = 0.6+0.2i. Bandingkan arah dan panjang panah sebelum dan setelah pembagian.','Initially (1+i)/(2+i) = 0.6+0.2i. Compare arrow directions and lengths before and after division.'),
  ],
  polar:[
    concept('angle','product','Perkalian: jumlah sudut','Multiplication: add angles','Sudut hasil kali adalah jumlah sudut masukan, modulo satu putaran.','A product angle is the sum of input angles, modulo a full turn.','Kalikan r₁eⁱᶿ¹ dan r₂eⁱᶿ². Aturan eksponen menjumlahkan sudut sementara faktor real mengalikan radius.','Multiply r₁eⁱᶿ¹ and r₂eⁱᶿ². The exponent law adds angles while the real factors multiply radii.','Untuk argumen, masukan bukan nol. Nilai utama Arg perlu dibungkus kembali ke (−π,π].','Inputs must be nonzero for arguments. Principal Arg must be wrapped back into (−π,π].',String.raw`z_1z_2=r_1r_2e^{i(\theta_1+\theta_2)}`,'Masukan pertama beradius 1 dan sudut yang dapat diubah; masukan kedua beradius 2 dan sudut 60°. Hasil beradius 2.','The first input has radius 1 and an adjustable angle; the second has radius 2 and angle 60°. The output has radius 2.'),
    concept('angle','inverse','Invers dan pangkat negatif','Inverse and negative powers','Invers membalik sudut dan mengganti radius r dengan 1/r.','An inverse reverses the angle and replaces radius r by 1/r.','Cari w agar zw = 1. Radius harus memenuhi rρ = 1 dan jumlah sudut harus 0 modulo 2π.','Find w such that zw = 1. Its radius satisfies rρ = 1, and the angle sum is zero modulo 2π.','z ≠ 0; pangkat bilangan bulat negatif membutuhkan invers.','z ≠ 0; negative integer powers require an inverse.',String.raw`(re^{i\theta})^{-1}=r^{-1}e^{-i\theta}`,'Contoh radius 2: panah invers beradius 0.5 dan berada di arah cermin sudut masukan.','For radius 2, the inverse arrow has radius 0.5 and the reflected input angle.'),
  ],
  roots:[concept('angle','roots','Akar target yang bukan 1','Roots of a target other than 1','Radius akar adalah akar ke-n radius target, sedangkan semua sudut target harus dibagi n.','Root radii are the nth root of the target radius, while all target angles must be divided by n.','Tulis w = ρeⁱᵅ. Dari wⁿ = reⁱᶿ, dapatkan ρⁿ = r dan nα = θ+2πk. Ambil k = 0 sampai n−1.','Write w = ρeⁱᵅ. From wⁿ = reⁱᶿ obtain ρⁿ = r and nα = θ+2πk. Use k = 0 through n−1.','n bilangan bulat positif; target bukan nol mempunyai n akar berbeda. Target nol hanya memiliki akar nol.','n is a positive integer; a nonzero target has n distinct roots. Zero has only the root zero.',String.raw`w_k=r^{1/n}e^{i(\theta+2\pi k)/n}`,'Tiga akar −8i mempunyai radius 2. Ubah sudut target untuk melihat ketiga akar berputar hanya sepertiga perubahan sudut.','The three roots of −8i have radius 2. Change the target angle: all roots rotate by one third of the angle change.')],
  disc:[
    concept('regions','openClosed','Terbuka, tertutup, atau keduanya bukan','Open, closed, or neither','Keanggotaan batas membedakan cakram terbuka, cakram tertutup, dan himpunan campuran.','Boundary membership distinguishes open discs, closed discs, and mixed sets.','Uji setiap titik: untuk terbuka harus ada lingkungan yang seluruhnya di dalam; untuk tertutup harus memuat seluruh titik batas.','Check each point: openness requires a neighborhood entirely inside; closedness requires every boundary point to belong.','Terbuka dan tertutup bukan dua pilihan yang selalu saling melengkapi. Himpunan kosong dan seluruh C keduanya terbuka serta tertutup.','Open and closed are not always complementary alternatives. The empty set and all of C are both open and closed.',String.raw`|z|<1,\quad |z|\le1,\quad 0<|z|\le1`,'Bandingkan tiga gambar: tepi putus-putus dikeluarkan, tepi penuh dimasukkan, dan lubang pusat membuat cakram campuran bukan terbuka maupun tertutup.','Compare three pictures: dashed edges are excluded, solid edges included, and the missing center makes the mixed disc neither open nor closed.'),
    concept('regions','connected','Terhubung dan domain','Connectedness and domains','Domain harus terbuka sekaligus terhubung: dua titik dapat dihubungkan di dalam daerah.','A domain must be open and connected: two points can be joined within the region.','Pada himpunan terbuka bidang, keterhubungan memberi lintasan poligonal. Dua cakram terpisah tidak terhubung walau masing-masing terbuka.','For open planar sets, connectedness gives polygonal paths. Two separate discs are disconnected even though each is open.','Keterhubungan tidak sama dengan tanpa lubang; anulus terbuka terhubung tetapi tidak simply connected.','Connected does not mean hole-free; an open annulus is connected but not simply connected.',String.raw`D\text{ domain}\iff D\text{ open and connected}`,'Gambar kiri mempunyai dua komponen. Gambar kanan adalah anulus: lintasan dapat mengelilingi lubang untuk menghubungkan titik.','The left picture has two components. The right is an annulus: a path can go around the hole to connect points.'),
    concept('regions','bounded','Terbatas dan titik akumulasi','Bounded sets and accumulation points','Terbatas berarti satu cakram beradius hingga dapat memuat seluruh himpunan. Titik akumulasi adalah titik yang didekati anggota lain.','Bounded means one finite-radius disc contains the whole set. An accumulation point is approached by other set members.','Untuk {1/n}, semua titik berada dalam radius 2 dan mendekati 0. Setiap lingkungan 0 berisi anggota himpunan, tetapi 0 bukan anggota.','For {1/n}, every point lies within radius 2 and approaches 0. Every neighborhood of 0 contains a member, but 0 is not itself a member.','Titik akumulasi tidak harus termasuk himpunan. Terbatas tidak menjamin tertutup.','Accumulation points need not belong to the set. Boundedness does not imply closedness.',String.raw`S=\{1/n:n\ge1\},\quad0\notin S,\quad0\in\overline S`,'Titik 1, 1/2, 1/3, … menumpuk dekat lingkaran kosong di 0. Lingkaran luar menunjukkan batas radius.','Points 1, 1/2, 1/3, … accumulate near the empty circle at 0. The outer circle shows a radius bound.'),
  ],
  map:[
    concept('angle','sector','Daerah dan konformalitas','Regions and conformality','z² menggandakan sudut global, tetapi menjaga sudut perpotongan lokal bila turunannya bukan nol.','z² doubles global polar angles but preserves local crossing angles where its derivative is nonzero.','Dari (reⁱᶿ)² = r²e²ⁱᶿ, sektor θ ∈ [0,π/2] menjadi sektor sudut [0,π]. Secara lokal, f′(z) = 2z mengalikan kedua arah oleh bilangan yang sama.','From (reⁱᶿ)² = r²e²ⁱᶿ, angles [0,π/2] become [0,π]. Locally f′(z) = 2z multiplies both directions by the same complex number.','Konformalitas memerlukan analitik dan f′ ≠ 0. Di 0, turunan z² nol dan pernyataan lokal itu tidak berlaku.','Conformality requires analyticity and f′ ≠ 0. At zero the derivative of z² vanishes, so that local statement fails.',String.raw`\rho=r^2,\quad\phi=2\theta,\quad f'(z)=2z`,'Dua sektor digambar berdampingan; perhatikan batas 90° di masukan menjadi 180° di keluaran.','Two sectors are shown side by side; the input’s 90° boundary becomes 180° in the output.'),
    concept('period','mapping','Eksponensial: garis menjadi lingkaran dan sinar','Exponential: lines become circles and rays','Garis vertikal x tetap menjadi lingkaran; garis mendatar y tetap menjadi sinar.','A vertical fixed-x line becomes a circle; a horizontal fixed-y line becomes a ray.','Pisahkan e^(x+iy) = eˣeⁱʸ. x menentukan radius positif dan y menentukan sudut. Variasikan hanya satu koordinat untuk mendapatkan dua keluarga kurva.','Split e^(x+iy) = eˣeⁱʸ. x controls positive radius and y controls angle. Vary just one coordinate to obtain the two curve families.','Eksponensial tidak mencapai 0; masukan yang berbeda 2πi punya keluaran sama.','The exponential never reaches zero; inputs differing by 2πi share the same output.',String.raw`x=c\mapsto|w|=e^c,\quad y=c\mapsto\arg w=c`,'Garis vertikal kiri diproyeksikan ke lingkaran kanan; ubah y untuk menggerakkan titik keluaran.','The left vertical line maps to the right circle; change y to move the output point.'),
  ],
  derivative:[
    concept('limits','paths','Limit dari semua arah','Limits from every direction','Satu limit kompleks harus sama untuk setiap cara mendekati titik.','A complex limit must agree for every approach to the point.','Untuk z̄/z dekat 0, sumbu real memberi 1, sedangkan sumbu imajiner memberi −1. Dua hasil berbeda sudah cukup menyangkal satu limit.','For z̄/z near zero, the real axis gives 1 and the imaginary axis −1. Two different results suffice to disprove a limit.','Menguji dua lintasan tidak cukup membuktikan limit ada. Limit harus memenuhi syarat ε–δ untuk seluruh lingkungan.','Two paths cannot prove existence. A limit must meet the ε–δ condition for a whole neighborhood.',String.raw`\frac{\bar x}{x}=1,\qquad\frac{\overline{iy}}{iy}=-1`,'Dua panah pendekatan menuju 0 memiliki keluaran berbeda. Rasio z̄/z tidak mempunyai limit di 0.','Two approach arrows toward zero have different outputs. The ratio z̄/z has no limit at zero.'),
    concept('limits','continuity','Limit komponen dan kekontinuan','Component limits and continuity','Limit u+iv ada tepat ketika kedua komponen realnya memiliki limit yang sesuai. Kontinu berarti limit itu sama dengan nilai fungsi.','A limit of u+iv exists exactly when both real components have matching limits. Continuity means that limit equals the function value.','Jarak kompleks memenuhi |u+iv|² = u²+v². Bila kedua komponen kecil maka jaraknya kecil; bila jaraknya kecil masing-masing komponen juga kecil.','Complex distance satisfies |u+iv|² = u²+v². Small components give small distance, and small distance bounds each component.','Nilai fungsi harus didefinisikan di titik untuk kontinuitas. Limit di titik berlubang masih dapat ada.','Continuity requires a value at the point. A limit may exist at a missing point.',String.raw`\lim f=u_0+iv_0\iff\lim u=u_0,\ \lim v=v_0`,'Contoh f(z)=z² di z₀=1: masukan dari berbagai arah memberi keluaran mendekati 1.','For f(z)=z² at z₀=1, inputs from different directions produce outputs approaching 1.'),
    concept('limits','infinity','Limit tak hingga lewat inversi','Limits at infinity through inversion','Inversi z ↦ 1/z menukar jauh dari asal dengan dekat asal.','Inversion z ↦ 1/z exchanges points far from the origin with points near it.','Karena |1/z| = 1/|z|, ambil |z| besar berarti |1/z| kecil. Ganti variabel ζ = 1/z untuk memakai definisi limit biasa.','Since |1/z| = 1/|z|, large |z| means small |1/z|. Substitute ζ = 1/z to use the ordinary limit definition.','Inversi membutuhkan z ≠ 0. Untuk limit f → ∞, periksa 1/f → 0 pada daerah tempat f bukan nol.','Inversion requires z ≠ 0. For f → ∞ check 1/f → 0 where f is nonzero.',String.raw`z\to\infty\iff1/z\to0,\quad f\to\infty\iff1/f\to0`,'Ubah radius R: panah masukan memanjang dan panah invers memendek; R dikalikan 1/R selalu 1.','Change radius R: the input arrow grows and the inverse shrinks; R times 1/R is always 1.'),
  ],
  cr:[
    concept('analytic','regularity','CR perlu dan CR cukup','Necessary CR and sufficient CR','CR di satu titik tanpa regularitas belum menjamin turunan kompleks.','CR at one point without regularity does not guarantee a complex derivative.','Jika u,v terdiferensialkan real, pendekatan linear memiliki empat koefisien. CR menyatukannya menjadi satu perkalian kompleks. Turunan parsial kontinu di sekitar titik merupakan syarat cukup yang mudah dipakai.','When u,v are real differentiable, the linear approximation has four coefficients. CR combines them into one complex multiplication. Continuous partial derivatives nearby give a convenient sufficient condition.','Gunakan CR bersama diferensiabilitas real; keberadaan parsial saja di satu titik tidak cukup.','Use CR with real differentiability; partial derivatives existing at just one point are insufficient.',String.raw`Df=\begin{pmatrix}u_x&-v_x\\v_x&u_x\end{pmatrix}`,'Matriks yang benar memetakan dua panah tegak lurus ke dua panah yang tetap tegak lurus dengan skala sama.','The valid matrix maps perpendicular input arrows to perpendicular output arrows with equal scale.'),
    concept('analytic','polar','CR dalam koordinat kutub','CR in polar coordinates','Koordinat kutub memakai arah radial dan tangensial, sehingga perubahan sudut mempunyai faktor panjang r.','Polar coordinates use radial and tangential directions, so angular change has a length factor r.','Terapkan aturan rantai x=r cosθ, y=r sinθ pada u,v. Ganti turunan Kartesius dengan turunan r,θ lalu gunakan CR untuk memperoleh ruᵣ=vθ dan uθ=−rvᵣ.','Apply the chain rule to x=r cosθ, y=r sinθ. Replace Cartesian derivatives by r,θ derivatives and use CR to obtain ruᵣ=vθ and uθ=−rvᵣ.','r > 0 karena koordinat sudut tidak terdefinisi di asal; syarat regularitas tetap berlaku.','r > 0 because angular coordinates are undefined at the origin; regularity conditions still apply.',String.raw`ru_r=v_\theta,\quad u_\theta=-rv_r`,'Satu perpindahan radial berpanjang Δr; satu perpindahan sudut kecil berpanjang kira-kira rΔθ.','A radial displacement has length Δr; a small angular displacement has length approximately rΔθ.'),
  ],
  harmonic:[concept('analytic','conjugate','Membangun konjugat harmonik','Constructing a harmonic conjugate','Konjugat harmonik melengkapi u agar u+iv analitik.','A harmonic conjugate completes u so that u+iv is analytic.','Untuk u=x²−y², CR memberi vᵧ=2x sehingga v=2xy+g(x). Persamaan vₓ=−uᵧ=2y memaksa g′=0. Jadi v=2xy+C.','For u=x²−y², CR gives vᵧ=2x, hence v=2xy+g(x). The relation vₓ=−uᵧ=2y forces g′=0, so v=2xy+C.','Konjugat selalu dapat dibangun lokal; secara global domain simply connected cukup. Di anulus, log|z| tidak mempunyai konjugat bernilai tunggal global.','Conjugates exist locally; a simply connected domain suffices globally. On an annulus log|z| has no global single-valued conjugate.',String.raw`u=x^2-y^2\implies v=2xy+C,\quad f=z^2+iC`,'Kurva level u dan v berpotongan tegak lurus kecuali di titik kritis 0. Keduanya adalah bagian real dan imajiner z².','The level curves of u and v cross orthogonally except at the critical point zero. They are the real and imaginary parts of z².')],
  exp:[
    concept('period','period','Periodisitas dan tidak ada nol','Periodicity and absence of zeros','Eksponensial berulang setiap 2πi dan tidak pernah nol.','The exponential repeats every 2πi and never vanishes.','Euler memberi e^(iy+2πi)=eⁱʸ. Radius eˣ selalu positif, sehingga keluaran tidak mungkin nol meskipun x sangat negatif.','Euler gives e^(iy+2πi)=eⁱʸ. The radius eˣ is always positive, so the output cannot be zero even for very negative x.','x,y real; periodisitas terjadi pada arah imajiner, bukan pada x.','x,y are real; periodicity occurs in the imaginary direction, not along x.',String.raw`e^{z+2\pi i}=e^z,\qquad |e^z|=e^x>0`,'Titik masukan yang berjarak vertikal 2π memiliki panah keluaran yang sama; eⁱπ = −1 bukan nol.','Input points separated vertically by 2π have the same output arrow; eⁱπ = −1, not zero.'),
    concept('period','law','Aturan penjumlahan dan turunan eksponensial','Exponential addition law and derivative','Penjumlahan masukan menjadi perkalian keluaran, dan perubahan kecil memberi turunan eᶻ.','Input addition becomes output multiplication, and small changes give derivative eᶻ.','Pisahkan e^(z+h)=eᶻeʰ. Bagi selisih oleh h: eᶻ(eʰ−1)/h. Limit faktor terakhir adalah 1 melalui deret eksponensial.','Split e^(z+h)=eᶻeʰ. The difference quotient is eᶻ(eʰ−1)/h. The final factor tends to 1 by the exponential series.','Eksponensial entire; tidak perlu memilih cabang.','The exponential is entire; no branch choice is required.',String.raw`e^{z+w}=e^ze^w,\qquad (e^z)'=e^z`,'Masukan 0 dan 2πi mempunyai keluaran 1 yang sama, tetapi itu tidak menghalangi turunan lokal ada di keduanya.','Inputs zero and 2πi share output 1, but local derivatives still exist at both.'),
  ],
  branch:[
    concept('powerBranch','power','Pangkat kompleks dan pilihan cabang','Complex powers and branch choice','Pangkat kompleks memakai eksponensial dari c kali logaritma, sehingga pilihan log menentukan hasil.','A complex power uses the exponential of c times a logarithm, so the log choice determines the result.','Log berubah sebesar 2πik. Setelah dikalikan c dan dieksponensialkan, nilai pangkat berubah dengan faktor e^(2πikc). Untuk c bulat faktor ini 1; untuk c lain belum tentu.','Log changes by 2πik. Multiplication by c and exponentiation change the power by e^(2πikc). For integer c this factor is 1; otherwise it need not be.', 'z ≠ 0; pilih cabang log pada domain yang sesuai. Nilai utama hanya satu pilihan.','z ≠ 0; choose a log branch on a suitable domain. The principal value is just one choice.',String.raw`z^c=e^{c\log z},\quad i^{-2i}=e^{\pi+4\pi k}`,'Ubah bilangan cabang k: i^(−2i) menghasilkan bilangan real positif yang berbeda, bukan hanya satu jawaban.','Change branch integer k: i^(−2i) produces different positive real values, not just one answer.'),
    concept('powerBranch','wrap','Mengapa aturan Log produk dapat gagal','Why the principal Log product rule can fail','Penjumlahan sudut dapat keluar dari rentang nilai utama.','An angle sum may leave the principal range.','Arg(−1)=π dan Arg(i)=π/2. Jumlahnya 3π/2, tetapi produk −i memiliki Arg=−π/2. Nilai log berbeda 2πi.','Arg(−1)=π and Arg(i)=π/2. The sum is 3π/2, but the product −i has Arg=−π/2. The logarithms differ by 2πi.','Identitas tanpa koreksi berlaku untuk log multivalued sebagai himpunan; jangan otomatis memakainya untuk Log utama.','The uncorrected identity holds for multivalued log as sets; do not apply it automatically to principal Log.',String.raw`\operatorname{Log}((-1)i)=-i\pi/2\ne i\pi+i\pi/2`,'Sudut 270° dan −90° menunjuk arah sama, tetapi nilai utama memakai −90°. Panah menunjukkan pembungkusan satu putaran.','Angles 270° and −90° point the same way, but the principal value uses −90°. The arrow shows wrapping by one turn.'),
  ],
  trig:[
    concept('trigZeros','zeros','Nol sinus dan kosinus kompleks','Zeros of complex sine and cosine','Nol sinus dan kosinus tetap berada pada sumbu real.','The zeros of sine and cosine remain on the real axis.','sin z=0 memberi e^(2iz)=1, jadi 2iz=2πik dan z=πk. cos z=0 memberi e^(2iz)=−1, jadi z=π/2+πk.','sin z=0 gives e^(2iz)=1, hence 2iz=2πik and z=πk. cos z=0 gives e^(2iz)=−1, hence z=π/2+πk.','k bilangan bulat. Pernyataan |sin z|≤1 tidak berlaku di seluruh C.','k is an integer. The bound |sin z|≤1 does not hold throughout C.',String.raw`\sin z=0\iff z=k\pi,\quad\cos z=0\iff z=\pi/2+k\pi`,'Nol sinus dan kosinus bergantian pada sumbu real; tidak ada nol di luar sumbu itu.','Sine and cosine zeros alternate on the real axis; there are no off-axis zeros.'),
    concept('trigZeros','growth','Modulus sinus di luar sumbu real','Sine magnitude away from the real axis','Bagian imajiner dapat membuat modulus sinus jauh lebih besar dari 1.','The imaginary part can make the sine magnitude much larger than 1.','Dari sin(x+iy)=sin x cosh y+i cos x sinh y, kuadrat modulusnya adalah jumlah kuadrat dua komponen. Pakai cosh²y−sinh²y=1 untuk memperoleh sin²x+sinh²y.','From sin(x+iy)=sin x cosh y+i cos x sinh y, square and add the components. Use cosh²y−sinh²y=1 to obtain sin²x+sinh²y.','x,y real. Batas real hanya berlaku saat y=0.','x,y are real. The real bound applies only when y=0.',String.raw`|\sin(x+iy)|^2=\sin^2x+\sinh^2y`,'Pada x=0, sin(iy)=i sinh y. Ubah y untuk melihat tinggi keluaran tumbuh melebihi 1.','At x=0, sin(iy)=i sinh y. Change y to see the output height grow beyond 1.'),
  ],
  integral:[
    concept('ML','bound','Taksiran ML','The ML estimate','M membatasi besar setiap kontribusi; L adalah panjang lintasan tempat kontribusi dijumlahkan.','M bounds each contribution’s magnitude; L is the path length over which they accumulate.','Ketaksamaan segitiga integral memberi |∫f dz|≤∫|f||dz|. Ganti |f| dengan M dan integral |dz| dengan L.','The integral triangle inequality gives |∫f dz|≤∫|f||dz|. Replace |f| by M and ∫|dz| by L.','Batas M harus berlaku di seluruh lintasan; lintasan rectifiable. ML adalah batas atas, bukan nilai integral yang pasti.','M must bound the entire rectifiable path. ML is an upper bound, not the exact integral.',String.raw`\left|\int_Cf\,dz\right|\le\int_C|f||dz|\le ML`,'Untuk setengah lingkaran radius R dan f=1/z, M=1/R serta L=πR, sehingga ML=π untuk setiap R>0.','For a radius-R semicircle with f=1/z, M=1/R and L=πR, so ML=π for every R>0.'),
    concept('ML','orientation','Parametrisasi dan arah lintasan','Parameterization and path orientation','dz menghitung arah serta besar perpindahan, bukan sekadar panjang.','dz accounts for direction as well as displacement size, not just length.','Untuk z(t)=Reⁱᵗ, dz=iReⁱᵗdt. Membalik parameter membalik tanda dz, sehingga nilai integral berubah tanda tetapi taksiran ML tetap.','For z(t)=Reⁱᵗ, dz=iReⁱᵗdt. Reversing the parameter reverses dz, changing the integral sign while leaving ML unchanged.','Lintasan piecewise smooth; nyatakan titik awal, akhir, dan interval parameter.','The path is piecewise smooth; specify endpoints and the parameter interval.',String.raw`\int_{-C}f\,dz=-\int_Cf\,dz`,'Panah berlawanan pada setengah lingkaran menghasilkan +iπ dan −iπ untuk f=1/z.','Opposite arrows on the semicircle give +iπ and −iπ for f=1/z.'),
    concept('circleIntegral','power','Mengapa hanya pangkat −1 bertahan','Why only the −1 power survives','Integral satu putaran penuh zⁿ nol kecuali n=−1.','The integral of zⁿ over one full circle vanishes except when n=−1.','Substitusi z=Reⁱᵗ menghasilkan iR^(n+1)e^i(n+1)t. Jika n+1 bukan nol, eksponensial berputar dan integralnya membatalkan diri; jika nol, integran konstan i.','Substitute z=Reⁱᵗ to obtain iR^(n+1)e^i(n+1)t. Nonzero n+1 produces rotations that cancel; zero n+1 leaves the constant i.','n bilangan bulat, R>0, orientasi positif satu putaran. Lingkaran tidak melewati asal.','n is an integer, R>0, and the circle makes one positive turn without passing through zero.',String.raw`\oint_{|z|=R}z^n dz=\begin{cases}2\pi i&n=-1\\0&n\ne-1\end{cases}`,'Ubah pangkat n: panah integran berputar kecuali saat n=−1. Inilah dasar koefisien residu.','Change n: the integrand arrow rotates except at n=−1. This is the basis of the residue coefficient.'),
  ],
  primitive:[
    concept('holes','goursat','Teorema Cauchy–Goursat','Cauchy–Goursat theorem','Fungsi analitik pada dan di dalam kontur sederhana tertutup memiliki integral nol.','A function analytic on and inside a simple closed contour has zero integral.','Daerah dapat dibagi menjadi bagian kecil. Integral sisi dalam saling menghapus karena arah berlawanan; analitik membuat sisa tiap bagian mengecil cukup cepat. Ini sketsa alasan pembuktian subdivisi.','Subdivide the region into small pieces. Interior edges cancel because their orientations oppose; analyticity makes each piece’s remainder sufficiently small. This illustrates the subdivision proof idea.','Kontur sederhana tertutup piecewise smooth; fungsi analitik pada lingkungan kontur dan seluruh interior.','The contour is simple, closed and piecewise smooth; f is analytic near the contour and its entire interior.',String.raw`\oint_C f(z)\,dz=0`,'Panah sisi bersama dua petak berlawanan dan menghapus. Hanya batas luar yang tersisa.','Arrows on shared edges oppose and cancel. Only the outer boundary remains.'),
    concept('holes','hole','Lubang, antiturunan global, deformasi','Holes, global primitives, and deformation','Analitik di sepanjang lintasan saja tidak menjamin integral tertutup nol.','Analyticity along a path alone does not force a closed integral to vanish.','1/z analitik di C tanpa 0, tetapi kontur yang mengelilingi 0 memberi 2πi. Batas luar dapat dideformasi ke batas kecil di sekitar lubang, bukan ke satu titik tanpa menyeberangi singularitas.','1/z is analytic on C excluding zero, but a loop around zero integrates to 2πi. The outer boundary deforms to a small boundary around the hole, not to a point without crossing the singularity.','Domain simply connected cukup agar setiap fungsi analitik memiliki antiturunan. Pada domain berlubang, periksa integral mengelilingi lubang.','A simply connected domain suffices for analytic functions to have primitives. On domains with holes check loop integrals.',String.raw`\oint_Cf\,dz=\sum_j\oint_{C_j}f\,dz`,'Lingkaran luar dan lingkaran kecil mengelilingi lubang yang sama memberi integral sama bila keduanya berorientasi positif.','The outer circle and the small circle around the same hole have equal integrals when both have positive orientation.'),
  ],
  cauchy:[],
  series:[
    concept('series','taylor','Taylor dan radius konvergensi','Taylor series and convergence radius','Deret Taylor berkembang dari pusat analitik sampai singularitas terdekat membatasi radius.','A Taylor series extends from an analytic center until the nearest singularity limits its radius.','Untuk 1/(1−z), jumlah hingga Sₙ=1+z+…+zⁿ memenuhi (1−z)Sₙ=1−z^(n+1). Jika |z|<1, suku terakhir menuju nol sehingga Sₙ→1/(1−z).','For 1/(1−z), the finite sum Sₙ satisfies (1−z)Sₙ=1−z^(n+1). When |z|<1, the last term vanishes and Sₙ→1/(1−z).','|z|<1 untuk contoh ini. Pernyataan di dalam cakram tidak otomatis meliputi batas |z|=1.','This example requires |z|<1. Interior convergence does not automatically include |z|=1.',String.raw`\frac1{1-z}=\sum_{n=0}^\infty z^n,\quad|z|<1`,'Ubah banyak suku N pada z=0.5. Jumlah mendekati 2; titik singular di z=1 berada tepat di batas cakram.','Change the number of terms N at z=0.5. The sum approaches 2; the singular point z=1 lies on the convergence boundary.'),
    concept('series','annulus','Laurent dan daerah anulus','Laurent series and annular regions','Fungsi yang sama dapat memiliki deret Laurent berbeda pada anulus berbeda.','The same function can have different Laurent expansions on different annuli.','Untuk 1/[z(1−z)], pada 0<|z|<1 gunakan 1/z+1+z+…. Pada |z|>1, tulis 1/(1−z)=−z⁻¹/(1−z⁻¹), sehingga diperoleh −z⁻²−z⁻³−….','For 1/[z(1−z)], use 1/z+1+z+… on 0<|z|<1. For |z|>1 rewrite 1/(1−z)=−z⁻¹/(1−z⁻¹), obtaining −z⁻²−z⁻³−….','Pilih anulus sebelum mengembangkan. Deret tidak berlaku melintasi singularitas 0 atau 1.','Choose an annulus before expanding. A series cannot cross singularities zero or one.',String.raw`\frac1{z(1-z)}=\begin{cases}z^{-1}+1+z+\cdots&0<|z|<1\\-z^{-2}-z^{-3}-\cdots&|z|>1\end{cases}`,'Dua daerah berwarna berbeda memakai dua ekspansi; koefisien z⁻¹ bahkan berbeda karena anulusnya berbeda.','The two colored regions use different expansions; even the z⁻¹ coefficient differs because the annuli differ.'),
  ],
  singularities:[
    concept('singularity','removable','Singularitas dapat dihapuskan','Removable singularities','Lubang dapat diisi bila fungsi mendekati satu nilai hingga.','A missing value can be filled when the function approaches a finite limit.','sin z/z=1−z²/3!+…. Tidak ada pangkat negatif Laurent, sehingga definisikan nilai di 0 sebagai 1 dan fungsi menjadi analitik.','sin z/z=1−z²/3!+…. There are no negative Laurent powers, so setting the value at zero to 1 makes the function analytic.','Fungsi analitik pada lingkungan terhapus; terbatas dekat pusat cukup untuk keterhapusan.','The function is analytic on a punctured neighborhood; boundedness near the center suffices for removability.',String.raw`\lim_{z\to0}\sin z/z=1`,'Kurva real sin x/x memiliki satu lubang di (0,1); titik penuh menunjukkan nilai yang mengisi lubang. Ini irisan real fungsi kompleks.','The real slice sin x/x has a hole at (0,1); the filled point shows the value that removes it.'),
    concept('singularity','pole','Kutub dan orde kutub','Poles and pole order','Kutub orde m berarti pangkat negatif terendah adalah −m dan jumlahnya hingga.','A pole of order m has lowest Laurent exponent −m and finitely many negative powers.','Tulis f(z)=φ(z)/(z−a)^m dengan φ analitik dan φ(a)≠0. Mengalikan dengan (z−a)^m menghilangkan ledakan tepat pada orde m.','Write f=φ(z)/(z−a)^m with analytic φ and φ(a)≠0. Multiplication by (z−a)^m removes the blow-up exactly at order m.','φ(a) ≠ 0 penting: jika φ juga nol, orde kutub dapat lebih kecil atau singularitas hilang.','φ(a)≠0 is essential: a numerator zero may lower the pole order or remove the singularity.',String.raw`f(z)=\phi(z)/(z-a)^m,\quad\phi(a)\ne0`,'Pada f=1/z², memotong radius r menjadi setengah membuat modulus empat kali lebih besar.','For f=1/z², halving radius r makes the magnitude four times larger.'),
  ],
  residue:[
    concept('residue','simple','Residu kutub sederhana','Simple-pole residue','Kalikan dengan z−a untuk menyisakan koefisien pangkat −1.','Multiply by z−a to isolate the −1 coefficient.','Jika f=p/q dan q memiliki nol sederhana di a, maka q(z)≈q′(a)(z−a). Rasio setelah pembatalan menuju p(a)/q′(a).','If f=p/q and q has a simple zero at a, q(z)≈q′(a)(z−a). After cancellation the ratio tends to p(a)/q′(a).','p,q analitik dekat a; q(a)=0 dan q′(a)≠0. p(a)=0 dapat memberi residu nol dan singularitas dapat dihapuskan.','p,q are analytic near a; q(a)=0 and q′(a)≠0. A numerator zero may give residue zero and a removable singularity.',String.raw`\operatorname{Res}_af=\lim_{z\to a}(z-a)f=\frac{p(a)}{q'(a)}`,'Untuk 1/[z(z−1)], kutub 0 memiliki residu −1 dan kutub 1 memiliki +1. Pilih radius kontur untuk melihat kutub yang ikut dijumlahkan.','For 1/[z(z−1)], pole zero has residue −1 and pole one +1. Change the contour radius to see which poles are included.'),
    concept('residue','higher','Residu kutub orde lebih tinggi','Higher-order pole residue','Pada kutub orde m, residu berasal dari koefisien Taylor ke-(m−1) pembilang yang regular.','At a pole of order m, the residue comes from the (m−1)th Taylor coefficient of the regular numerator.','Kembangkan φ=c₀+c₁(z−a)+…. Setelah dibagi (z−a)^m, suku dengan indeks m−1 menjadi pangkat −1. Koefisiennya φ^(m−1)(a)/(m−1)!.','Expand φ=c₀+c₁(z−a)+…. Division by (z−a)^m turns the term indexed m−1 into power −1, with coefficient φ^(m−1)(a)/(m−1)!.','m positif bulat dan φ analitik. Orde kutub tidak sama dengan residu.','m is a positive integer and φ is analytic. Pole order is not the residue.',String.raw`\operatorname{Res}_a\frac{\phi(z)}{(z-a)^m}=\frac{\phi^{(m-1)}(a)}{(m-1)!}`,'Contoh eᶻ/z²: koefisien 1 dari suku linear eᶻ menjadi koefisien 1/z, sehingga residunya 1 meskipun kutub berorde 2.','For eᶻ/z², coefficient 1 of the linear exponential term becomes the 1/z coefficient: residue 1 despite pole order 2.'),
  ],
  basis:[
    concept('sectionPoint','ratio','Titik pembagi dan titik tengah','Division points and midpoints','Titik M yang membagi AB memakai kombinasi berbobot koordinat ujung.','A point dividing AB uses a weighted combination of endpoint coordinates.','Dari M−A=k(B−M), pindahkan semua suku M ke kiri: (1+k)M=A+kB. Bagi dengan 1+k; k=1 memberi titik tengah.','From M−A=k(B−M), collect M terms: (1+k)M=A+kB. Divide by 1+k; k=1 gives the midpoint.','k≠−1. k>0 memberi pembagian internal, sedangkan k negatif dapat memberi pembagian eksternal.','k≠−1. Positive k gives internal division; negative k may give external division.',String.raw`M=\frac{A+kB}{1+k}`,'A=(0,0), B=(6,3). Ubah k dan lihat M bergerak; pada k=2, AM:MB=2:1 dan M=(4,2).','With A=(0,0), B=(6,3), move k. At k=2, AM:MB=2:1 and M=(4,2).'),
    concept('vectors','basis','Bebas linear dan koordinat unik','Linear independence and unique coordinates','Dua arah membentuk basis bidang jika tidak sejajar.','Two directions form a plane basis if they are not parallel.','Kolom e₁,e₂ membentuk matriks B. Menulis v=Bc memberi satu solusi c untuk setiap v tepat ketika det B≠0. Jika determinan nol, kedua arah runtuh ke satu garis.','Put e₁,e₂ in columns of B. The equation v=Bc has a unique solution for every v exactly when det B≠0. A zero determinant collapses the directions to one line.','Dalam dimensi n, perlu n arah bebas linear yang merentang ruang.','In dimension n, use n independent spanning directions.',String.raw`Bc=v,\quad\det B\ne0\implies c=B^{-1}v`,'Ubah arah e₂ dari sejajar menjadi tidak sejajar dengan e₁. Luas jajargenjang berubah dari nol menjadi bukan nol.','Move e₂ from parallel to nonparallel with e₁. The parallelogram area changes from zero to nonzero.'),
  ],
  products:[
    concept('vectors','dot','Dot product dan proyeksi','Dot product and projection','Dot product mengukur bagian satu vektor sepanjang arah vektor lain.','The dot product measures how much of one vector lies along another.','Pada v sepanjang sumbu x, komponen mendatar u adalah |u|cosθ. Kalikan dengan |v| untuk memperoleh u·v=|u||v|cosθ.','For v along the x-axis, u’s horizontal component is |u|cosθ. Multiply by |v| to get u·v=|u||v|cosθ.','Untuk proyeksi ke v, v≠0. Rumus koordinat u₁v₁+u₂v₂+u₃v₃ memakai basis ortonormal.','Projection onto v requires v≠0. The component sum uses an orthonormal basis.',String.raw`u\cdot v=|u||v|\cos\theta,\quad\operatorname{proj}_vu=\frac{u\cdot v}{|v|^2}v`,'Ubah sudut u: proyeksi positif saat lancip, nol saat tegak lurus, dan negatif saat tumpul.','Change u’s angle: its projection is positive for acute angles, zero at a right angle, and negative for obtuse angles.'),
    concept('vectors','cross','Cross product dan luas','Cross product and area','Cross product tegak lurus dua masukan dan panjangnya sama dengan luas jajargenjang.','The cross product is perpendicular to both inputs and its magnitude is the parallelogram area.','Pakai alas |u| dan tinggi |v|sinθ. Luas menjadi |u||v|sinθ; aturan tangan kanan memilih arah normal, dan menukar u,v membalik tanda.','Use base |u| and height |v|sinθ. The area is |u||v|sinθ; the right-hand rule chooses the normal and swapping u,v reverses it.','Cross product biasa ini berlaku di ruang Euclidean 3D dengan orientasi yang dipilih.','This ordinary cross product is in oriented Euclidean 3D.',String.raw`|u\times v|=|u||v|\sin\theta,\quad v\times u=-u\times v`,'Dua sisi membentuk jajargenjang. Ubah sudut untuk melihat luas nol saat sejajar dan maksimum saat tegak lurus.','The two sides span a parallelogram. Change the angle: area is zero for parallel sides and maximal for perpendicular sides.'),
    concept('vectors','triple','Volume, koplanaritas, dan triple product','Volume, coplanarity, and triple product','Triple product mengukur volume berarah; nol berarti tiga vektor koplanar.','The triple product measures signed volume; zero means the three vectors are coplanar.','Cross product dua vektor memberi luas normal. Dot dengan vektor ketiga mengambil komponen tingginya, sehingga luas dikalikan tinggi menjadi volume.','The cross product of two vectors gives an area normal. Dotting with the third extracts its height, giving area times height.','Volume geometris adalah nilai mutlak. Vektor nol juga memberi volume nol. Identitas triple product memakai dot dan cross Euclidean.','Geometric volume is the absolute value. A zero vector also gives zero volume. Triple-product identities use Euclidean dot and cross products.',String.raw`u\cdot(v\times w)=\det(u,v,w),\quad u\times(v\times w)=(u\cdot w)v-(u\cdot v)w`,'Alas berluas 6 dan tinggi h memberi volume berarah 6h. Saat h=0, kotak runtuh menjadi bidang.','Base area 6 and height h give signed volume 6h. At h=0 the box collapses into a plane.'),
  ],
  plane:[
    concept('linePlane','line','Persamaan parametrik garis','Parametric line equations','Satu titik dan satu arah tidak nol menentukan satu garis.','One point and one nonzero direction determine a line.','Semua titik garis didapat dengan menambahkan t kali arah d ke titik p. Koordinat simetris berasal dari menyamakan nilai t dalam setiap komponen.','Every line point adds t times direction d to p. Symmetric equations equate the t values obtained from the components.','d≠0; jika suatu komponen arah nol, pertahankan koordinat itu konstan dan jangan membaginya dengan nol.','d≠0; a zero direction component means that coordinate is constant, not a division by zero.',String.raw`r=p+td,\quad t\in\mathbb R`,'p=(1,1), d=(2,1). Ubah t untuk memindahkan titik; nilai negatif bergerak ke arah sebaliknya.','For p=(1,1), d=(2,1), change t to move the point; negative values move in the opposite direction.'),
    concept('linePlane','intersection','Bidang melalui titik dan irisan dua bidang','Planes through points and two-plane intersections','Normal tegak lurus semua arah dalam bidang. Arah irisan dua bidang tegak lurus kedua normal.','A normal is perpendicular to every direction in a plane. A two-plane intersection direction is perpendicular to both normals.','Dari tiga titik tidak segaris ambil AB×AC sebagai normal. Untuk dua bidang, n₁×n₂ memberi arah garis perpotongan.','For three noncollinear points take AB×AC as the normal. For two planes, n₁×n₂ gives their intersection-line direction.','Tiga titik harus tidak segaris; n₁×n₂≠0 untuk garis irisan tunggal. Normal sejajar memberi bidang sejajar atau berimpit.','The three points must be noncollinear; n₁×n₂≠0 gives an intersection line. Parallel normals give parallel or coincident planes.',String.raw`n\cdot(r-p)=0,\quad d=n_1\times n_2`,'Bidang x=0 dan y=0 bertemu di sumbu z. Normalnya e₁ dan e₂; hasil cross adalah e₃.','Planes x=0 and y=0 meet on the z-axis. Their normals are e₁ and e₂; their cross product is e₃.'),
    concept('pencil','planes','Pensil bidang','Plane pencils','Kombinasi dua persamaan bidang mempertahankan garis perpotongan bersama.','Combining two plane equations preserves their common intersection line.','Jika titik memenuhi π₁=0 dan π₂=0, titik itu juga memenuhi λπ₁+μπ₂=0. Variasikan koefisien untuk memutar bidang di sekitar garis bersama.','A point satisfying π₁=0 and π₂=0 also satisfies λπ₁+μπ₂=0. Vary coefficients to rotate planes about the common line.','(λ,μ)≠(0,0). Dua bidang dasar harus berbeda dan berpotongan untuk pensil dengan satu garis bersama.','(λ,μ)≠(0,0). Distinct intersecting base planes give a pencil with one common line.',String.raw`\lambda\pi_1+\mu\pi_2=0`,'Keluarga cosθ x+sinθ y=0 berputar mengelilingi sumbu z; garis bersama selalu tetap.','The family cosθ x+sinθ y=0 rotates around the z-axis; the common line stays fixed.'),
  ],
  projection:[
    concept('angles','linePlane','Sudut garis, bidang, dan normal','Angles between lines, planes, and normals','Sudut garis–bidang adalah komplemen sudut garis–normal.','The line–plane angle complements the line–normal angle.','Dot product normal n dan arah d memberi cosβ. Karena α=90°−β, sinα=|n·d|/(|n||d|). Dua garis memakai arah; dua bidang memakai normal.','The dot product gives cosβ between normal n and direction d. Since α=90°−β, sinα=|n·d|/(|n||d|). Two lines use directions; two planes use normals.','Arah dan normal bukan nol. Nilai mutlak memilih sudut tak berorientasi antara 0° dan 90°.','Directions and normals must be nonzero. Absolute values select the unoriented angle between 0° and 90°.',String.raw`\sin\angle(d,\pi)=\frac{|n\cdot d|}{|n||d|}`,'Garis mendatar mewakili bidang dalam irisan 2D. Ubah arah d dan lihat α+β=90°.','The horizontal line represents the plane in a 2D section. Change d and watch α+β=90°.'),
    concept('angles','pointLine','Jarak titik ke garis','Point-to-line distance','Jarak tegak lurus adalah tinggi jajargenjang yang dibentuk arah garis dan vektor menuju titik.','Perpendicular distance is the height of the parallelogram formed by the line direction and the vector to the point.','Cross product mengukur alas kali tinggi. Bagi panjang cross oleh panjang arah garis untuk membuang alas dan menyisakan tinggi.','The cross product measures base times height. Divide its magnitude by the line direction length to leave the height.','Arah d≠0; pilih titik A pada garis. Panjang arah boleh berbeda, hasil jarak tetap.','d≠0; choose A on the line. Rescaling d leaves the distance unchanged.',String.raw`\operatorname{dist}(P,\ell)=\frac{|(P-A)\times d|}{|d|}`,'P=(2,h) di atas sumbu x memiliki jarak |h|. Segmen miring menuju asal lebih panjang dari kaki tegak lurus.','P=(2,h) above the x-axis has distance |h|. The slanted segment to the origin is longer than the perpendicular foot.'),
    concept('angles','skew','Jarak dua garis bersilangan','Distance between skew lines','Normal bersama dua arah menentukan jalur terpendek di antara garis bersilangan.','The common normal to the two directions determines the shortest separation between skew lines.','n=d₁×d₂ tegak lurus kedua arah. Ambil komponen A₂−A₁ pada normal unit n/|n| untuk memperoleh jarak.','n=d₁×d₂ is perpendicular to both directions. Project A₂−A₁ onto n/|n| to obtain the distance.','d₁×d₂≠0. Untuk garis sejajar, rumus ini membagi nol dan harus diganti rumus titik–garis.','d₁×d₂≠0. For parallel lines this divides by zero; use the point-to-line formula instead.',String.raw`d=\frac{|(A_2-A_1)\cdot(d_1\times d_2)|}{|d_1\times d_2|}`,'Garis berarah x pada z=0 dan garis berarah y pada z=h tidak berpotongan jika h≠0. Jaraknya |h|.','An x-directed line at z=0 and a y-directed line at z=h do not meet when h≠0. Their distance is |h|.'),
  ],
  power:[
    concept('circles','complete','Pusat dan radius dari persamaan umum','Center and radius from a general equation','Melengkapkan kuadrat mengungkap pusat dan menentukan apakah lingkaran nyata ada.','Completing the square reveals the center and whether a real circle exists.','x²−2αx=(x−α)²−α² dan begitu pula y. Pindahkan konstanta sehingga radius kuadrat menjadi α²+β²−σ.','Use x²−2αx=(x−α)²−α² and likewise for y. Moving the constants gives squared radius α²+β²−σ.','R²>0 lingkaran nyata, R²=0 satu titik, R²<0 himpunan kosong di bidang nyata.','R²>0 gives a real circle, R²=0 a point, R²<0 an empty real set.',String.raw`(x-\alpha)^2+(y-\beta)^2=\alpha^2+\beta^2-\sigma`,'Untuk x²+y²−4x+2y+σ=0, pusat tetap (2,−1). Ubah σ dan lihat radius √(5−σ).','For x²+y²−4x+2y+σ=0, the center stays (2,−1). Change σ to see radius √(5−σ).'),
    concept('circles','secant','Kuasa titik dari dua potongan secant','Point power from secant intersections','Produk jarak berarah ke dua potongan lingkaran tidak bergantung pada arah secant.','The product of directed distances to two circle intersections is independent of the secant direction.','Substitusi garis P+td unit ke |P+td−O|²=R² memberi persamaan kuadrat dalam t. Produk kedua akar t₁t₂ adalah konstanta |P−O|²−R² menurut Vieta.','Substitute the line P+td with unit d into |P+td−O|²=R². The product of roots t₁t₂ is the constant |P−O|²−R² by Vieta.','Gunakan jarak berarah, bukan dua panjang selalu positif. Untuk titik di dalam, satu akar negatif dan satu positif.','Use directed distances, not two always-positive lengths. For an interior point one root is negative and the other positive.',String.raw`t_1t_2=|P-O|^2-R^2`,'Lingkaran radius 2, P=(x,0). Potongan pada −2 dan 2 memberi t₁=−2−x serta t₂=2−x; produknya x²−4.','For radius 2 and P=(x,0), intersections −2 and 2 give t₁=−2−x and t₂=2−x; their product is x²−4.'),
    concept('conicTangent','polar','Mengapa polar melalui titik singgung','Why a polar passes through tangency points','Normal di titik T lingkaran adalah T−O. Garis PT singgung tepat ketika PT tegak lurus normal itu.','The circle normal at T is T−O. PT is tangent exactly when it is perpendicular to that normal.','Dari (P−T)·(T−O)=0 dan |T−O|²=R², peroleh (P−O)·(T−O)=R². Itulah persamaan garis polar untuk variabel T.','From (P−T)·(T−O)=0 and |T−O|²=R² obtain (P−O)·(T−O)=R², the polar line equation in T.','O pusat, R>0, P≠O. Dua titik singgung nyata hanya untuk P di luar lingkaran.','O is the center, R>0, P≠O. Two real tangency points exist only for exterior P.',String.raw`(P-O)\cdot(T-O)=R^2`,'Pada radius 2 dan P=(3,0), titik kontak memiliki x=4/3. Garis vertikal melalui keduanya adalah polar P.','For radius 2 and P=(3,0), contact points have x=4/3. The vertical line through them is P’s polar.'),
  ],
  radical:[
    concept('pencil','circles','Pensil lingkaran dan pusat radikal','Circle pencils and radical centers','Kombinasi persamaan lingkaran menjaga titik dasar bersama; tiga sumbu radikal dapat mempunyai satu pusat bersama.','Combining circle equations preserves common base points; three radical axes can share one radical center.','Kurangkan persamaan dua lingkaran untuk menghapus x²+y². Kesamaan kuasa menjadi garis. Kesamaan kuasa pertama-kedua dan kedua-ketiga juga memaksa pertama-ketiga.','Subtract two circle equations to cancel x²+y². Equal power becomes a line. Equality for first–second and second–third also implies first–third.','Untuk anggota pensil berupa lingkaran, koefisien x²+y² harus tidak nol. Kombinasi tertentu adalah garis radikal. Sumbu sejajar tidak memberi satu pusat hingga.','A pencil member is a circle only if its x²+y² coefficient is nonzero. Some combinations give the radical line. Parallel axes have no finite common center.',String.raw`\lambda f_1+\mu f_2=0`,'Dua lingkaran melalui titik atas dan bawah yang sama. Anggota lain pensil tetap melalui kedua titik itu.','Two circles pass through the same upper and lower points. Other pencil members still pass through both.'),
    concept('circles','sphere','Bola dan bidang singgung','Spheres and tangent planes','Bola adalah titik berjarak R dari pusat; bidang singgung tegak lurus radius pada titik sentuh.','A sphere consists of points at distance R from its center; a tangent plane is perpendicular to the contact radius.','Persamaan bola adalah |r−O|²=R². Gradien 2(r−O) memberi normal di T, sehingga bidang singgung memenuhi (T−O)·(r−T)=0.','The sphere equation is |r−O|²=R². Gradient 2(r−O) gives the normal at T, so the tangent plane satisfies (T−O)·(r−T)=0.','T berada pada bola dan R>0. Gambar irisan 2D memperlihatkan hubungan tegak lurus yang sama dalam 3D.','T lies on the sphere and R>0. The 2D cross-section shows the same perpendicular relation as in 3D.',String.raw`|r-O|^2=R^2,\quad(T-O)\cdot(r-O)=R^2`,'Radius ke puncak bola tegak lurus bidang singgung. Irisan pusat menunjukkan garis singgung yang menyentuh sekali.','The radius to the sphere’s top is perpendicular to the tangent plane. A central cross-section shows one contact point.'),
  ],
  conic:[
    concept('conicTangent','ellipse','Garis singgung konik','Tangent lines to conics','Normal gradien pada titik konik memberi persamaan garis singgung.','The gradient normal at a conic point gives its tangent equation.','Untuk F=x²/a²+y²/b²−1, gunakan ∇F(P)·(r−P)=0. Karena P pada elips, konstanta menyederhana menjadi xx₀/a²+yy₀/b²=1.','For F=x²/a²+y²/b²−1 use ∇F(P)·(r−P)=0. Since P lies on the ellipse this simplifies to xx₀/a²+yy₀/b²=1.','P harus berada pada konik regular. Pada parabola y²=2px, konvensi buku memberi yy₀=p(x+x₀).','P must lie on a regular conic. For the textbook parabola y²=2px the tangent is yy₀=p(x+x₀).',String.raw`xx_0/a^2+yy_0/b^2=1,\quad yy_0=p(x+x_0)`,'Ubah sudut parameter P pada elips bersumbu 3 dan 2. Garis singgung berputar dan normal tetap tegak lurusnya.','Move parameter point P on the ellipse with semiaxes 3 and 2. The tangent rotates while its normal stays perpendicular.'),
    concept('conicTangent','eccentricity','Eksentrisitas dan direktriks','Eccentricity and directrices','Rasio jarak ke fokus terhadap jarak ke direktriks adalah eksentrisitas e.','The focus-distance to directrix-distance ratio is eccentricity e.','Untuk elips e=c/a<1 dan direktriks x=a/e. Identitas jarak fokus untuk titik elips memberi PF=e·dist(P,direktriks). Hiperbola mempunyai e>1; parabola e=1.','For an ellipse e=c/a<1 and directrix x=a/e. Its focal-distance identity gives PF=e·dist(P,directrix). A hyperbola has e>1 and a parabola e=1.','Untuk direktriks elips, c>0. Lingkaran c=0 mempunyai e=0 dan tidak memiliki direktriks hingga dalam bentuk ini.','For an ellipse’s directrix c>0. A circle has e=0 and no finite directrix in this form.',String.raw`PF=e\,\operatorname{dist}(P,d),\quad d:x=\pm a/e`,'Untuk a=3,b=2, c=√5 dan e=√5/3. Segmen fokus lebih pendek daripada segmen menuju direktriks dengan rasio e.','For a=3,b=2, c=√5 and e=√5/3. The focus segment is shorter than the directrix segment in ratio e.'),
  ],
  quadric:[
    ...['ellipsoid','oneSheet','twoSheets','cone','ellipticParaboloid','hyperbolicParaboloid'].map((mode,i)=>concept('quadrics',mode,['Elipsoid','Hiperboloid satu lembar','Hiperboloid dua lembar','Kerucut kuadrik','Paraboloid eliptik','Paraboloid hiperbolik'][i],['Ellipsoid','One-sheet hyperboloid','Two-sheet hyperboloid','Quadric cone','Elliptic paraboloid','Hyperbolic paraboloid'][i],['Semua tanda positif memberi permukaan tertutup.','Dua kuadrat positif dan satu negatif memberi satu permukaan terhubung.','Dua kuadrat positif dan ruas kanan negatif memisahkan dua lembar.','Ruas kanan nol membuat semua penampang mengecil menuju puncak.','Kuadrat x dan y dengan tanda sama memberi mangkuk.','Kuadrat dengan tanda berlawanan memberi pelana.'][i],['All positive signs give a closed surface.','Two positive squares and one negative give one connected surface.','Two positive squares and a negative right side separate two sheets.','A zero right side makes sections shrink to the vertex.','Same-sign x and y squares give a bowl.','Opposite-sign squares give a saddle.'][i],'Tetapkan z=h untuk membaca penampang horizontal. Persamaan menjadi kurva 2D; radius atau bentuknya berubah bersama h. Kumpulan penampang membentuk permukaan.','Set z=h to read horizontal sections. The equation becomes a 2D curve whose radius or shape changes with h. The sections assemble the surface.','a,b,c positif. Gambar proyeksi 3D bersifat skematis; penampang dan nilai radius mengikuti persamaan yang ditulis.','a,b,c are positive. The 3D projection is schematic; sections and radii follow the displayed equation.',[String.raw`x^2+y^2+z^2=1`,String.raw`x^2+y^2-z^2=1`,String.raw`x^2+y^2-z^2=-1`,String.raw`x^2+y^2-z^2=0`,String.raw`x^2+y^2=2z`,String.raw`x^2-y^2=2z`][i],'Ubah tinggi h. Lingkaran penampang ditampilkan jika radius kuadrat tidak negatif; jika negatif, penampang nyata kosong. Pelana mempunyai penampang hiperbola.','Change height h. A circular section appears when its squared radius is nonnegative; otherwise the real section is empty. The saddle has hyperbolic sections.')),
    concept('quadrics','ruling','Dua keluarga generator garis lurus','Two families of straight-line generators','Pelana dan hiperboloid satu lembar dapat memuat dua keluarga garis lurus.','A saddle and a one-sheet hyperboloid can contain two straight-line families.','Pada z=x²−y², tetapkan x−y=s sehingga z=s(x+y). Karena s konstan, dua persamaan itu linear dalam x,y,z. Menukar x−y dan x+y memberi keluarga kedua.','For z=x²−y² fix x−y=s, giving z=s(x+y). With s fixed these are linear equations in x,y,z. Exchanging x−y and x+y gives the other family.','Setiap titik garis harus memenuhi persamaan permukaan. Garis yang hanya memotong permukaan bukan generator.','Every point of the line must satisfy the surface equation. A line merely intersecting the surface is not a generator.',String.raw`x-y=s,\quad z=s(x+y)`,'Ubah s untuk memilih satu garis merah pada jaring pelana. Semua titik garis tetap berada pada permukaan.','Change s to select one red line on the saddle mesh. Every point of the line remains on the surface.'),
  ],
  eigen:[
    concept('matrix','form','Matriks bentuk kuadrat dan invariannya','Quadratic-form matrix and invariants','Matriks simetris menyimpan koefisien kuadrat dan suku silang.','A symmetric matrix stores square and cross-term coefficients.','Dalam xᵀAx, suku xy muncul dua kali dari a₁₂ dan a₂₁. Jadi koefisien silang 2a₁₂ memakai a₁₂ sebagai entri matriks. Trace dan determinan tetap setelah rotasi ortogonal.','In xᵀAx, xy appears twice from a₁₂ and a₂₁. A cross coefficient 2a₁₂ therefore uses a₁₂ as the matrix entry. Trace and determinant remain unchanged under orthogonal rotations.','A simetris untuk bentuk kuadrat real; transformasi ortogonal menjaga eigenvalue. Matriks diperbesar menyimpan suku linear dan konstanta.','A is symmetric for a real quadratic form; orthogonal changes preserve eigenvalues. The augmented matrix stores linear and constant terms.',String.raw`x^TAx+2a^Tx+a_{00},\quad I=\operatorname{tr}A,\ \delta=\det A,\ \Delta=\det\widetilde A`,'Bentuk x²+2xy+y² mempunyai A=[[1,1],[1,1]], trace 2 dan determinan 0. Kotak koefisien menyorot bahwa koefisien xy dibagi dua.','For x²+2xy+y², A=[[1,1],[1,1]], trace 2 and determinant zero. Coefficient boxes highlight halving the xy coefficient.'),
    concept('matrix','center','Pusat konik dari sistem linear','Conic centers from a linear system','Pusat menghapus suku linear setelah translasi koordinat.','A center removes the linear terms after translating coordinates.','Substitusi x=y+h memberi koefisien linear 2(Ah+a)ᵀy. Koefisien ini nol tepat ketika Ah+a=0.','Substituting x=y+h gives linear coefficient 2(Ah+a)ᵀy. It vanishes exactly when Ah+a=0.','A invertibel memberi satu pusat. A singular dapat memberi tidak ada pusat atau tak hingga pusat, bergantung a.','Invertible A gives one center. Singular A may give no center or infinitely many, depending on a.',String.raw`Ah+a=0`,'Bandingkan lingkaran dengan A=I dan parabola dengan A singular: lingkaran memiliki pusat; parabola tidak.','Compare a circle with A=I to a parabola with singular A: the circle has a center; the parabola does not.'),
  ],
  reduce:[
    concept('classification','conic','Tanda eigenvalue dan klasifikasi konik','Eigenvalue signs and conic classification','Sesudah rotasi dan translasi, tanda koefisien kuadrat mengungkap elips, hiperbola, atau parabola.','After rotation and translation, square-coefficient signs reveal an ellipse, hyperbola, or parabola.','Jika dua eigenvalue bukan nol bertanda sama, jumlah kuadrat memberi elips bila konstanta mengizinkan solusi. Tanda berlawanan memberi hiperbola. Satu arah kuadrat nol dengan suku linear tidak nol memberi parabola.','Two nonzero eigenvalues of the same sign give an ellipse when the constant permits real solutions. Opposite signs give a hyperbola. One zero quadratic direction with a nonzero linear term gives a parabola.','Untuk klasifikasi, periksa juga ruas kanan dan degenerasi. Δ=0 tidak selalu berarti dua garis nyata berbeda: dapat berupa titik atau himpunan kosong.','Check the right side and degeneracies too. Δ=0 does not always mean two distinct real lines: it can give a point or an empty set.',String.raw`X^2+qY^2=1,\quad\delta=q`,'Ubah q: q>0 memberi elips, q<0 hiperbola, q=0 dua garis X=±1. Parabola membutuhkan suku linear pada arah nol.','Change q: q>0 gives an ellipse, q<0 a hyperbola, q=0 two lines X=±1. A parabola requires a linear term in the zero direction.'),
    concept('quadrics','degenerate','Kuadrik degenerat: silinder dan bidang','Degenerate quadrics: cylinders and planes','Koordinat yang tidak muncul membuat kurva diperpanjang sepanjang arah itu.','An absent coordinate extends a curve along that direction.','Jika x²+y²=1 tidak memuat z, setiap titik lingkaran boleh mempunyai semua nilai z. Ini silinder. Jika persamaan menjadi x²=1, solusinya dua bidang x=±1.','If x²+y²=1 omits z, every circle point allows all z values, giving a cylinder. If the equation becomes x²=1, it gives two planes x=±1.','Rank, suku linear, dan konstanta semuanya perlu diperiksa; determinan nol saja belum menentukan jenisnya.','Rank, linear terms and the constant all matter; a zero determinant alone does not determine the type.',String.raw`x^2+y^2=1\quad(z\text{ free}),\qquad x^2=1`,'Penampang lingkaran yang sama pada semua tinggi membentuk silinder. Tidak ada penyempitan pada arah z.','The same circle section at every height forms a cylinder. There is no narrowing along z.'),
  ],
  affine:[
    concept('transform','homothety','Translasi, homoteti, dan orientasi','Translation, homothety, and orientation','Translasi memindahkan semua titik dengan vektor sama. Homoteti mengalikan semua perpindahan dari pusat dengan k.','Translation moves every point by one vector. Homothety scales displacements from its center by k.','T(x)=B x+c memisahkan bagian linear dan translasi. B=kI memberi homoteti; determinan k² mengubah luas. Determinan negatif dari peta lain membalik orientasi.','T(x)=Bx+c separates linear and translation parts. B=kI gives homothety; determinant k² scales area. A negative determinant of another map reverses orientation.','B invertibel untuk transformasi afin. k=0 meruntuhkan seluruh ruang menjadi satu titik.','B must be invertible for an affine transformation. k=0 collapses the entire space to one point.',String.raw`T(x)=kx+c,\quad\text{area factor}=k^2`,'Ubah k dan lihat segitiga diperbesar terhadap pusat; k negatif memindahkannya ke sisi berlawanan tanpa membalik orientasi 2D.','Change k to scale the triangle about its center; negative k sends it to the opposite side without reversing 2D orientation.'),
    concept('transform','fixed','Titik tetap transformasi afin','Fixed points of an affine map','Titik tetap adalah titik yang tidak dipindahkan transformasi.','A fixed point is left unmoved by the transformation.','T(x)=x berarti Bx+c=x, jadi (B−I)x=−c. Jika B−I invertibel, solusinya satu. Translasi bukan nol tidak memiliki titik tetap.','T(x)=x means Bx+c=x, so (B−I)x=−c. If B−I is invertible there is one solution. A nonzero translation has no fixed point.','B−I dapat singular walau B invertibel; saat itu sistem dapat tidak konsisten atau memiliki banyak solusi.','B−I can be singular even when B is invertible; the system may then have no solutions or many.',String.raw`(B-I)x=-c`,'Pada T(x)=2x+(1,0), titik tetap (−1,0) dipetakan ke dirinya. Panah titik lain menjauh dari pusat itu.','For T(x)=2x+(1,0), fixed point (−1,0) maps to itself. Other point arrows move away from that center.'),
  ],
  isometry:[
    concept('transform','reflection','Refleksi dan dua kali refleksi','Reflection and reflecting twice','Refleksi membalik komponen tegak lurus cermin dan menjaga komponen sejajar.','Reflection reverses the component perpendicular to the mirror and preserves the parallel one.','Untuk cermin y=0, (x,y)→(x,−y). Menerapkan aturan dua kali mengembalikan y, jadi σ²=id. Untuk bidang z=c, z′=2c−z.','For mirror y=0, (x,y)→(x,−y). Applying it twice restores y, so σ²=id. For plane z=c, z′=2c−z.','Refleksi adalah isometri dan determinannya −1. Dua refleksi terhadap cermin berbeda tidak selalu identitas.','Reflection is an isometry with determinant −1. Two reflections in different mirrors need not give identity.',String.raw`(x,y)\mapsto(x,-y),\quad\sigma^2=\mathrm{id}`,'Dua segitiga adalah bayangan cermin. Titik dan bayangannya berjarak sama dari garis cermin.','The triangles are mirror images. A point and its reflection are equally distant from the mirror.'),
    concept('transform','similarity','Similaritas: jarak dikalikan k','Similarity: distances multiply by k','Similaritas menggabungkan isometri, skala positif, dan translasi.','A similarity combines an isometry, a positive scale, and a translation.','Untuk B=kQ dengan QᵀQ=I, |Bv|²=k²vᵀQᵀQv=k²|v|². Maka semua jarak dikalikan k dan semua sudut tetap.','For B=kQ with QᵀQ=I, |Bv|²=k²vᵀQᵀQv=k²|v|². All distances multiply by k and all angles remain unchanged.','k>0; faktor luas 2D adalah k² dan faktor volume 3D adalah k³.','k>0; the 2D area factor is k² and the 3D volume factor is k³.',String.raw`B=kQ,\quad|T(P)-T(Q)|=k|P-Q|`,'Ubah k untuk melihat semua sisi segitiga berubah dengan rasio sama; sudut-sudutnya tetap.','Change k: all triangle sides change by the same ratio while angles stay fixed.'),
    concept('transform','inversion','Inversi lingkaran bukan transformasi afin','Circle inversion is not affine','Inversi mengganti radius r dengan k/r dan menjaga arah dari pusat.','Inversion replaces radius r with k/r and preserves the direction from its center.','Syarat OM·OM′=k memberi M′=O+k(M−O)/|M−O|². Penyebut bergantung pada M, jadi peta bukan linear ditambah translasi.','OM·OM′=k gives M′=O+k(M−O)/|M−O|². The denominator depends on M, so the map is not linear plus translation.','M≠O dan k>0. Garis yang tidak melewati O menjadi lingkaran melalui O, sehingga kesejajaran tidak terjaga.','M≠O and k>0. A line not through O becomes a circle through O, so parallelism is not preserved.',String.raw`M'=O+\frac{k(M-O)}{|M-O|^2}`,'Untuk k=1, radius 2 menjadi 0.5. Titik pada lingkaran unit tetap, dan menerapkan inversi dua kali mengembalikan titik.','For k=1, radius 2 becomes 0.5. Unit-circle points stay fixed, and applying inversion twice restores a point.'),
  ],
  group:[
    concept('groupTable','axioms','Empat aksioma dalam tabel operasi','The four axioms in an operation table','Tertutup, asosiatif, identitas, dan invers adalah empat pemeriksaan berbeda.','Closure, associativity, identity, and inverses are four separate checks.','Pada Z₄, jumlah modulo 4 selalu kembali ke tabel. Nol mempertahankan setiap anggota; setiap baris mempunyai nol untuk invers. Asosiativitas diwarisi dari penjumlahan bilangan bulat.','In Z₄, modular addition stays within the table. Zero preserves each element; every row contains zero, giving inverses. Associativity is inherited from integer addition.','Tabel Latin saja tidak membuktikan asosiativitas. Operasi grup juga tidak wajib komutatif.','A Latin table alone does not prove associativity. Group operations need not be commutative.',String.raw`(a+b)+c=a+(b+c)\pmod4`,'Pilih a: baris a memperlihatkan identitas dan kolom −a modulo 4 menghasilkan nol.','Choose a: row a shows the identity and column −a modulo 4 gives zero.'),
    concept('groupTable','cancellation','Pembatalan dan solusi unik','Cancellation and unique solutions','Pembatalan memakai invers, sehingga tidak membutuhkan komutativitas.','Cancellation uses inverses and does not require commutativity.','Dari ab=ac, kalikan di kanan oleh a⁻¹ untuk memperoleh b=c. Untuk ax=b, solusi x=a⁻¹b; urutan tidak boleh ditukar.','From ab=ac multiply on the left by a⁻¹ to obtain b=c. For ax=b the solution is x=a⁻¹b; do not reverse the order.','a anggota grup sehingga inversnya ada. Dalam gelanggang, elemen bukan nol belum tentu dapat dibatalkan.','a is a group element so its inverse exists. In a ring a nonzero element need not be cancellable.',String.raw`ab=ac\implies b=c,\quad ax=b\implies x=a^{-1}b`,'Pada Z₄, a+x=3 memiliki tepat satu solusi untuk setiap a. Setiap baris tabel mempunyai 3 tepat sekali.','In Z₄, a+x=3 has exactly one solution for every a. Each table row contains 3 exactly once.'),
    concept('S3','inverse','Mengapa invers produk berurutan terbalik','Why product inverses reverse order','Untuk membatalkan dua tindakan, batalkan tindakan terakhir lebih dulu.','To undo two actions, undo the last action first.','(ab)(b⁻¹a⁻¹)=a(bb⁻¹)a⁻¹=e. Jika memakai a⁻¹b⁻¹, unsur yang perlu saling membatalkan tidak berdampingan.','(ab)(b⁻¹a⁻¹)=a(bb⁻¹)a⁻¹=e. Using a⁻¹b⁻¹ may leave inverse pairs separated.', 'Aturan berlaku di setiap grup, termasuk nonabelian. Menukar urutan hanya aman bila faktor komut.','The rule holds in every group, including nonabelian ones. Swapping order is safe only when the factors commute.',String.raw`(ab)^{-1}=b^{-1}a^{-1}`,'Contoh permutasi: lakukan τ=(23) lalu σ=(12). Untuk kembali, lakukan σ lagi lalu τ, karena keduanya adalah invers dirinya.','Apply τ=(23), then σ=(12). To return, apply σ then τ, since both are their own inverses.'),
  ],
  cyclic:[
    concept('subgroupTest','closure','Uji subgrup dan syarat hingga','Subgroup test and the finite-set condition','Subset bukan kosong menjadi subgrup jika tertutup terhadap ab⁻¹. Pada subset hingga, tertutup perkalian saja cukup.','A nonempty subset is a subgroup when closed under ab⁻¹. For finite subsets closure under multiplication suffices.','Uji ab⁻¹ memberi e=aa⁻¹, invers lewat eb⁻¹, dan produk lewat invers yang sudah diperoleh. Pada himpunan hingga, pangkat akhirnya berulang sehingga identitas dan invers muncul.','The ab⁻¹ test gives identity aa⁻¹, inverses eb⁻¹, then products using those inverses. In a finite closed set powers eventually repeat, producing identity and inverses.','Subset harus bukan kosong. Pada himpunan tak hingga, Z positif tertutup penjumlahan tetapi bukan subgrup Z.','The subset must be nonempty. Positive integers are closed under addition but are not a subgroup of Z.',String.raw`H\le G\iff H\ne\varnothing,\ ab^{-1}\in H\ (a,b\in H)`,'Bandingkan {0,2,4} dan {0,1,2} di Z₆. Yang kedua gagal karena 1+2=3 berada di luar subset.','Compare {0,2,4} and {0,1,2} in Z₆. The second fails because 1+2=3 lies outside it.'),
    concept('subgroupTest','order','Orde anggota dan kapan pangkat kembali','Element order and returning powers','Orde menghitung panjang siklus pangkat, bukan nilai angka anggotanya.','Order counts the power-cycle length, not the numerical value of the element.','Pada Zₙ aditif, ka=0 modulo n tepat ketika n membagi ka. Nilai k positif terkecil adalah n/gcd(a,n). Siklus pangkat mengulang setelah itu.','In additive Zₙ, ka=0 mod n exactly when n divides ka. The least positive k is n/gcd(a,n), after which the power cycle repeats.','Rumus n/gcd berlaku untuk grup siklik modulo n; pada grup umum gunakan pangkat dan identitas.','The n/gcd formula applies to cyclic modular groups; in a general group use powers and the identity.',String.raw`o([a])=n/\gcd(a,n),\quad a^k=e\iff o(a)\mid k`,'Pilih a dalam Z₁₂: a=4 menghasilkan 0→4→8→0, sehingga orde 3, bukan 4.','Choose a in Z₁₂: a=4 gives 0→4→8→0, so its order is 3, not 4.'),
    concept('S3','centralizer','Centralizer, pusat, konjugasi, dan irisan','Centralizers, centers, conjugation, and intersections','Centralizer berisi anggota yang komut dengan a; pusat komut dengan semua anggota.','A centralizer contains elements commuting with a; the center commutes with every element.','Jika x,y komut dengan a, maka xy dan x⁻¹ juga komut dengan a, sehingga C(a) subgrup. Irisan subgrup tetap tertutup. Konjugasi g⁻¹Hg memindahkan subgrup melalui automorfisma.','If x,y commute with a, so do xy and x⁻¹, giving a subgroup C(a). Intersections preserve closure. Conjugation g⁻¹Hg transports a subgroup by an automorphism.','Pusat adalah irisan semua centralizer. Konjugat subgrup tidak harus sama dengan subgrup asal.','The center is the intersection of all centralizers. A conjugate subgroup need not equal the original.',String.raw`C(a)=\{g:ga=ag\},\quad Z(G)=\bigcap_a C(a)`,'Di S₃, C((12))={e,(12)} tetapi pusat S₃={e}. Konjugasi memindahkan (12) ke transposisi lain.','In S₃, C((12))={e,(12)} but Z(S₃)={e}. Conjugation sends (12) to another transposition.'),
  ],
  cosets:[
    concept('coset','lagrange','Teorema Lagrange dari partisi koset','Lagrange’s theorem from a coset partition','Koset membagi grup menjadi potongan dengan ukuran sama.','Cosets partition a group into equally sized pieces.','Peta h↦hg adalah bijeksi H→Hg. Koset berbeda tidak bertumpang tindih dan semua anggota G berada pada satu koset. Hitung ukuran total sebagai banyak koset dikali ukuran satu koset.','The map h↦hg is a bijection H→Hg. Distinct cosets do not overlap and every G element belongs to one. Count total size as coset count times coset size.','G hingga untuk pernyataan pembagian orde. Pembagi |G| belum tentu menjadi orde subgrup pada grup umum.','G is finite for the order-divisibility statement. A divisor of |G| need not be a subgroup order in a general group.',String.raw`|G|=[G:H]|H|,\quad |H|\mid|G|`,'Di Z₁₂, H={0,4,8}. Ada empat kotak koset, masing-masing tiga anggota: 12=4×3.','In Z₁₂, H={0,4,8}. Four coset boxes have three elements each: 12=4×3.'),
    concept('coset','equality','Kapan dua koset sama','When two cosets coincide','Dua koset yang memiliki satu anggota bersama sebenarnya sama seluruhnya.','Two cosets sharing one element are identical as sets.','Jika h₁a=h₂b, maka ab⁻¹=h₁⁻¹h₂∈H. Menggeser H oleh unsur H tidak mengubahnya, sehingga Ha=Hb.','If h₁a=h₂b then ab⁻¹=h₁⁻¹h₂ lies in H. Translating H by one of its elements leaves H unchanged, so Ha=Hb.','Pilih konsisten koset kanan Ha atau kiri aH. Rumus pembeda harus mengikuti konvensi yang dipilih.','Keep right cosets Ha or left cosets aH consistent. The equality test must match the convention.',String.raw`Ha=Hb\iff ab^{-1}\in H`,'Pada Z₁₂ dengan H={0,4,8}, wakil 1 dan 5 menghasilkan kotak sama {1,5,9}; wakil 2 menghasilkan kotak lain.','In Z₁₂ with H={0,4,8}, representatives 1 and 5 give the same box {1,5,9}; representative 2 gives a different one.'),
  ],
  kernel:[
    concept('homomorphism','operation','Homomorfisma mempertahankan operasi','Homomorphisms preserve operations','Mengoperasikan dahulu atau memetakan dahulu harus memberi hasil sama.','Operating first or mapping first must give the same result.','Untuk φ:Z₁₂→Z₃, ambil sisa modulo 3. Karena penjumlahan dan pengurangan kelipatan 3 komut, φ(a+b)=φ(a)+φ(b). Identitas dan invers mengikuti dari aturan operasi.','For φ:Z₁₂→Z₃ reduce modulo 3. Addition commutes with removal of multiples of 3, giving φ(a+b)=φ(a)+φ(b). Identity and inverse preservation follow.','Grup domain dan target harus ditentukan; Z₁₂→Z₅ lewat sisa bukan homomorfisma penjumlahan modulo 12.','Specify domain and target groups; reduction Z₁₂→Z₅ is not a homomorphism for addition modulo 12.',String.raw`\varphi(ab)=\varphi(a)\varphi(b),\quad\varphi(e)=e',\quad\varphi(a^{-1})=\varphi(a)^{-1}`,'Dua jalur diagram komutatif memakai 4 dan 5: jumlah di Z₁₂ adalah 9 dan semua jalur menghasilkan 0 di Z₃.','The commuting diagram uses 4 and 5: their Z₁₂ sum is 9 and both paths give zero in Z₃.'),
    concept('homomorphism','injective','Kernel trivial tepat ketika injektif','Trivial kernel exactly when injective','Kernel mencatat informasi yang hilang; kernel trivial berarti tidak ada dua anggota berbeda yang digabung.','The kernel records lost information; a trivial kernel means no distinct elements merge.','Jika φ(a)=φ(b), maka φ(ab⁻¹)=e′ sehingga ab⁻¹∈kerφ. Kernel {e} memaksa a=b; sebaliknya injektif hanya mengirim e ke e′.','If φ(a)=φ(b), then φ(ab⁻¹)=e′, so ab⁻¹ is in the kernel. Kernel {e} forces a=b; conversely an injective map sends only e to e′.','φ harus homomorfisma. Untuk fungsi sembarang, satu serat tunggal di identitas tidak menjamin injektif.','φ must be a homomorphism. For arbitrary functions one singleton identity fiber does not imply injectivity.',String.raw`\varphi\text{ injective}\iff\ker\varphi=\{e\}`,'Proyeksi Z₁₂→Z₃ menggabungkan empat anggota per kelas dan kernel {0,3,6,9}; peta identitas tidak menggabungkan anggota.','Projection Z₁₂→Z₃ merges four elements per class with kernel {0,3,6,9}; the identity map merges none.'),
    concept('S3','normal','Normalitas adalah kestabilan himpunan','Normality is setwise stability','Normal berarti konjugasi menjaga subgrup sebagai satu himpunan, bukan memperbaiki setiap anggotanya.','Normality means conjugation preserves the subgroup as a set, not that it fixes every element.','Kernel normal karena φ(g⁻¹kg)=φ(g)⁻¹e′φ(g)=e′. Pada S₃, konjugasi menukar dua siklus tiga dalam A₃ tetapi tetap menjaga A₃.','A kernel is normal because φ(g⁻¹kg)=φ(g)⁻¹e′φ(g)=e′. In S₃ conjugation swaps the two 3-cycles in A₃ while preserving A₃.','Periksa semua g∈G. H={e,(12)} di S₃ tidak normal; A₃ normal.','Check all g∈G. H={e,(12)} in S₃ is not normal; A₃ is.',String.raw`g^{-1}Ng=N\iff gN=Ng`,'Bandingkan H={e,(12)} dan A₃={e,(123),(132)} sebelum dan setelah konjugasi oleh (23).','Compare H={e,(12)} and A₃={e,(123),(132)} before and after conjugation by (23).'),
  ],
  quotient:[
    concept('S3','quotient','Mengapa wakil koset harus bebas pilihan','Why coset representative choice must not matter','Operasi kuosien harus memberi kelas hasil sama untuk setiap pilihan wakil.','A quotient operation must produce the same output class for every representative choice.','Normalitas memungkinkan faktor N dipindah melintasi wakil dan diserap lagi. Pada subgrup tidak normal, dua wakil dari kelas sama dapat menghasilkan kelas berbeda setelah perkalian.','Normality lets N factors move past representatives and be absorbed again. With a nonnormal subgroup, representatives of the same class can yield different product classes.','N normal diperlukan untuk struktur grup dengan perkalian koset ini. Himpunan koset tetap ada tanpa normalitas.','N must be normal for this coset multiplication to give a group. The coset set exists without normality.',String.raw`(aN)(bN)=abN\quad(N\triangleleft G)`,'Di S₃, H={e,(12)} tidak normal. Ganti wakil e dengan (12), lalu kalikan di kanan oleh wakil lain untuk melihat kelas hasil berubah.','In S₃, H={e,(12)} is not normal. Replace representative e by (12), then multiply on the right by another representative to see the result class change.'),
    concept('S3','commutator','Kuosien abelian dari grup nonabelian','Abelian quotients of nonabelian groups','G/N abelian berarti kegagalan komutasi di G seluruhnya hilang di N.','G/N being abelian means all failures to commute in G vanish in N.','[a][b]=[b][a] tepat ketika aba⁻¹b⁻¹∈N. Pada S₃/A₃, semua permutasi hanya dibaca menurut tanda, sehingga hasilnya grup dua anggota abelian.','[a][b]=[b][a] exactly when aba⁻¹b⁻¹ lies in N. S₃/A₃ records only permutation signs and is the abelian group of order two.','N normal; G sendiri tidak harus abelian.','N is normal; G itself need not be abelian.',String.raw`G/N\text{ abelian}\iff aba^{-1}b^{-1}\in N\quad\forall a,b`,'σ=(12) dan τ=(23) tidak komut di S₃, tetapi kedua hasil στ dan τσ sama-sama genap sehingga menjadi kelas yang sama di kuosien.','σ=(12) and τ=(23) do not commute in S₃, but both στ and τσ are even and become the same quotient class.'),
  ],
  cycles:[
    concept('S3','composition','Komposisi permutasi: kanan bekerja dulu','Permutation composition: right factor acts first','στ berarti mengikuti τ, kemudian σ. Mengubah urutan dapat mengubah hasil.','στ means follow τ then σ. Reversing the order may change the result.','Lacak setiap anggota melalui dua baris panah. Untuk σ=(12),τ=(23), angka 1 menuju 1 lewat τ lalu 2 lewat σ. Urutan sebaliknya membawa 1 ke 3.','Trace each element through two arrow rows. With σ=(12), τ=(23), 1 goes to 1 under τ then 2 under σ. Reversing the order sends 1 to 3.','Konvensi di sini kanan-ke-kiri, sama seperti komposisi fungsi. Nyatakan konvensi sebelum menghitung.','This uses right-to-left function composition. State the convention before calculating.',String.raw`(\sigma\tau)(s)=\sigma(\tau(s))`,'Dua diagram panah memperlihatkan στ=(123) dan τσ=(132), sehingga S₃ tidak abelian.','The arrow diagrams show στ=(123) and τσ=(132), so S₃ is not abelian.'),
    concept('cycles','disjoint','Siklus lepas, invers, dan orde KPK','Disjoint cycles, inverses, and LCM order','Siklus lepas bekerja pada anggota berbeda, sehingga komut dan kembali serentak setelah KPK panjangnya.','Disjoint cycles act on different elements, so they commute and return simultaneously after the LCM of their lengths.','Siklus tiga kembali setiap tiga langkah dan siklus dua setiap dua langkah. Langkah kembali bersama terkecil adalah 6. Membalik arah setiap siklus memberi invers.','A 3-cycle returns every three steps and a 2-cycle every two. Their smallest simultaneous return is 6. Reversing every cycle gives the inverse.','Siklus harus lepas untuk aturan komutasi ini. Dekomposisi memuat juga titik tetap jika perlu.','The cycles must be disjoint for this commutation rule. Include fixed points where needed.',String.raw`o(\sigma)=\operatorname{lcm}(3,2)=6`,'Ubah langkah k pada (123)(45); kedua orbit pulang serentak hanya saat k kelipatan 6.','Change k for (123)(45); both orbits return simultaneously only at multiples of 6.'),
    concept('cycles','count','Mengapa |Sₙ|=n!','Why |Sₙ|=n!','Bijeksi memilih keluaran berbeda untuk setiap masukan.','A bijection assigns a different output to every input.','Masukan pertama punya n pilihan; kedua n−1 karena satu keluaran sudah dipakai; lanjut sampai satu pilihan terakhir. Kalikan n(n−1)…1.','The first input has n choices, the second n−1 because one output is used, and so on to the final single choice. Multiply n(n−1)…1.','Himpunan memiliki n anggota berbeda. Jika pengulangan keluaran diizinkan, yang dihitung adalah fungsi, bukan permutasi.','The set has n distinct elements. Allowing repeated outputs counts functions rather than permutations.',String.raw`|S_n|=n!`,'Untuk tiga masukan, pohon pilihan mempunyai 3×2×1=6 daun; keenam bijeksi ditampilkan.','For three inputs the choice tree has 3×2×1=6 leaves; all six bijections are shown.'),
  ],
  parity:[concept('cycles','parity','Siklus menjadi transposisi dan paritas','Cycles become transpositions and parity','Siklus panjang k membutuhkan k−1 pertukaran dalam penguraian standar.','A k-cycle uses k−1 swaps in its standard decomposition.','Tahan anggota pertama sebagai poros: (a₁…aₖ)=(a₁aₖ)…(a₁a₂). Tiap pertukaran bertanda −1, jadi tandanya (−1)^(k−1). Untuk siklus lepas, jumlahkan k−1.','Hold the first element as pivot: (a₁…aₖ)=(a₁aₖ)…(a₁a₂). Each swap has sign −1, so the sign is (−1)^(k−1). For disjoint cycles add their k−1 counts.','Panjang siklus genap memberi permutasi ganjil. Penguraian tidak unik, tetapi paritas jumlah pertukaran tetap.','Even cycle length gives an odd permutation. Decompositions are not unique, but swap-count parity is invariant.',String.raw`\operatorname{sgn}(a_1\cdots a_k)=(-1)^{k-1}`,'Siklus (1234) diurai menjadi (14)(13)(12): tiga transposisi, sehingga ganjil.','The cycle (1234) factors as (14)(13)(12): three transpositions, hence odd.')],
  ring:[
    concept('ringTable','distribute','Dua operasi dan distributivitas','Two operations and distributivity','Penjumlahan dan perkalian harus berinteraksi melalui dua aturan distributif.','Addition and multiplication must interact through both distributive laws.','Gelanggang adalah grup abelian terhadap penjumlahan, perkalian asosiatif, dan a(b+c)=ab+ac serta (b+c)a=ba+ca. Tidak semua buku mewajibkan identitas perkalian.','A ring is an abelian additive group with associative multiplication and both distributive laws. Not every textbook requires a multiplicative identity.','Pada gelanggang nonkomutatif, (a+b)²=a²+ab+ba+b²; jangan mengganti ab+ba dengan 2ab tanpa syarat komutasi.','In a noncommutative ring (a+b)²=a²+ab+ba+b²; do not replace ab+ba by 2ab without commutation.',String.raw`a(b+c)=ab+ac,\quad(a+b)^2=a^2+ab+ba+b^2`,'Tabel penjumlahan dan perkalian Z₆ adalah dua tabel berbeda. Untuk a=2,b=1,c=3, kedua jalur distributif memberi 2 modulo 6.','Addition and multiplication in Z₆ use different tables. For a=2,b=1,c=3, both distributive paths give 2 modulo 6.'),
    concept('ringTable','units','Unit, pembagi nol, dan pembatalan','Units, zero divisors, and cancellation','Unit memiliki invers; pembagi nol memiliki faktor bukan nol yang produknya nol.','A unit has an inverse; a zero divisor has a nonzero factor whose product is zero.','Pada Zₙ, Bézout memberi invers saat gcd(a,n)=1. Jika d=gcd(a,n)>1 untuk a bukan nol, a·(n/d)=0 modulo n dan n/d bukan nol.','In Zₙ, Bézout gives an inverse when gcd(a,n)=1. If d=gcd(a,n)>1 for nonzero a, then a·(n/d)=0 modulo n with nonzero n/d.','Nol bukan unit. Untuk klasifikasi pembagi nol ini, a bukan nol. Dalam daerah integral setiap a≠0 dapat dibatalkan, tetapi belum tentu punya invers.','Zero is not a unit. Here zero-divisor classification takes nonzero a. In a domain nonzero elements cancel but need not be units.',String.raw`[a]\text{ unit in }\mathbb Z_n\iff\gcd(a,n)=1`,'Pilih a di Z₆: 1 dan 5 mempunyai invers; 2,3,4 menghasilkan nol dengan faktor bukan nol.','Choose a in Z₆: 1 and 5 have inverses; 2,3,4 yield zero with nonzero factors.'),
    concept('ringTable','hierarchy','Gelanggang → daerah integral → lapangan','Rings → integral domains → fields','Menambah syarat mempersempit jenis gelanggang.','Adding conditions narrows the ring types.','Z₆ komutatif tetapi punya pembagi nol; Z adalah daerah integral tetapi 2 tidak memiliki invers bulat; Z₅ lapangan karena semua anggota bukan nol memiliki invers.','Z₆ is commutative but has zero divisors; Z is an integral domain but 2 has no integer inverse; Z₅ is a field because all nonzero elements have inverses.','Untuk domain dan field gunakan konvensi komutatif dengan 1≠0. Herstein mengizinkan gelanggang umum tanpa 1.','For domains and fields use the commutative 1≠0 convention. Herstein allows general rings without 1.',String.raw`\text{fields}\subset\text{integral domains}\subset\text{commutative rings}`,'Kotak bersarang menempatkan Z₅, Z, dan Z₆ pada tingkat berbeda. Syarat yang hilang ditulis pada setiap contoh.','Nested boxes place Z₅, Z and Z₆ at different levels, with each missing condition labeled.'),
  ],
  ideal:[
    concept('ideal','absorb','Ideal dibanding subgelanggang','Ideals versus subrings','Ideal menyerap perkalian oleh setiap anggota gelanggang asal.','An ideal absorbs multiplication by every element of the ambient ring.','Closure internal tidak cukup. Z adalah subgelanggang Q, tetapi 1∈Z dikali 1/2∈Q keluar dari Z. Sebaliknya, kelipatan 2 di Z menyerap perkalian oleh setiap bilangan bulat.','Internal closure is insufficient. Z is a subring of Q, but 1∈Z times 1/2∈Q leaves Z. By contrast multiples of 2 in Z absorb multiplication by every integer.','Pada gelanggang nonkomutatif, ideal dua sisi harus menyerap perkalian dari kiri dan kanan.','In noncommutative rings a two-sided ideal must absorb multiplication on both sides.',String.raw`rI\subseteq I,\quad Ir\subseteq I\quad(r\in R)`,'Panah gagal keluar dari kotak Z ketika dikalikan 1/2; panah perkalian kelipatan 2 oleh 3 tetap di dalam ideal (2).','A failed arrow leaves Z when multiplied by 1/2; multiplying a multiple of 2 by 3 stays inside ideal (2).'),
    concept('ideal','isomorphism','Homomorfisma gelanggang dan kuosien','Ring homomorphisms and quotient rings','Kernel gelanggang mempertahankan kedua operasi dan membentuk ideal, sehingga kuosien cocok dengan image.','A ring kernel respects both operations and forms an ideal, so its quotient matches the image.','Jika φ(a)=φ(b), selisih a−b berada di kernel. Koset menandai persis anggota yang digabung. Definisikan [a][b]=[ab]; penyerapan ideal membuat pilihan wakil tidak berpengaruh.','If φ(a)=φ(b), a−b lies in the kernel. Cosets record exactly the merged elements. Define [a][b]=[ab]; ideal absorption makes representatives irrelevant.','Kernel ideal dua sisi; φ mempertahankan + dan ×. Isomorfisma menuju image, atau seluruh target jika φ surjektif.','The kernel is two-sided; φ preserves + and ×. The isomorphism reaches the image, or the whole target when φ is surjective.',String.raw`R/\ker\varphi\cong\varphi(R)`,'Z→Z₃ menggabungkan semua bilangan dengan sisa sama; diagram menguji penjumlahan dan perkalian kelas [1] dan [2].','Z→Z₃ merges integers with the same remainder; the diagram checks addition and multiplication of classes [1] and [2].'),
    concept('ideal','gaussian','Ideal maksimal dalam Z dan Z[i]','Maximal ideals in Z and Z[i]','Maksimalitas diperiksa melalui apakah kuosien menjadi lapangan.','Maximality can be checked by whether the quotient is a field.','Z/(p) adalah lapangan tepat ketika p prima. Untuk Z[i]/(3), gunakan i²=−1=2 di F₃: polinom x²+1 tidak punya akar di F₃, memberi lapangan sembilan anggota. Modulo 5, (2+i)(2−i)=5 memberi pembagi nol.','Z/(p) is a field exactly when p is prime. For Z[i]/(3), i²=−1=2 in F₃: x²+1 has no root over F₃, giving a field with nine elements. Modulo 5, (2+i)(2−i)=5 gives zero divisors.','R komutatif dengan 1, ideal proper. Prima integer tidak selalu menghasilkan ideal maksimal di Z[i].','R is commutative with 1 and the ideal proper. An integer prime need not give a maximal ideal in Z[i].',String.raw`\mathbb Z[i]/(3)\cong\mathbb F_3[x]/(x^2+1),\quad\#=9`,'Sembilan kotak a+bi dengan a,b∈{0,1,2} adalah sembilan anggota kuosien modulo 3.','Nine boxes a+bi with a,b∈{0,1,2} are the quotient’s nine elements modulo 3.'),
  ],
  division:[
    concept('polynomial','degree','Derajat produk dan algoritma pembagian','Product degree and the division algorithm','Suku utama menentukan derajat; pembagian menghapus suku utama berulang kali.','Leading terms determine degree; division repeatedly removes the leading term.','Untuk f,g bukan nol atas lapangan, koefisien utama produk tidak nol, jadi deg(fg)=deg f+deg g. Dalam pembagian, bagi dua suku utama lalu kurangkan hasil kali untuk menurunkan derajat sisa.','For nonzero f,g over a field, the product’s leading coefficient is nonzero, so degrees add. In division, divide the leading terms and subtract the product to lower remainder degree.','g≠0. Pembagian koefisien utama memerlukan invers; atas gelanggang umum algoritma ini bisa gagal.','g≠0. Dividing leading coefficients requires inverses; the algorithm may fail over a general ring.',String.raw`f=qg+r,\quad\deg r<\deg g`,'x³+1 dibagi x+1 menghasilkan x²−x+1 dengan sisa nol; setiap pengurangan membuang satu suku utama.','Dividing x³+1 by x+1 gives x²−x+1 and zero remainder; each subtraction removes a leading term.'),
    concept('polynomial','field','Irreduksibilitas bergantung pada lapangan','Irreducibility depends on the field','Faktor yang diizinkan berubah bersama lapangan koefisien.','Permitted factors change with the coefficient field.','x²−2 tidak punya akar rasional, jadi irreduksibel atas Q karena berderajat dua. Atas R, √2 tersedia dan menghasilkan dua faktor linear.','x²−2 has no rational root and is irreducible over Q because it is quadratic. Over R, √2 is available and gives two linear factors.','Tanpa akar cukup hanya pada derajat 2 atau 3. x⁴+4 tidak punya akar real tetapi terfaktor menjadi dua kuadrat atas Q.','No roots suffices only for degrees 2 or 3. x⁴+4 has no real roots but factors into two quadratics over Q.',String.raw`x^2-2=(x-\sqrt2)(x+\sqrt2)\text{ over }\mathbb R`,'Pohon yang berhenti pada x²−2 di Q bercabang menjadi dua daun linear di R. Bandingkan dengan faktorisasi x⁴+4.','The tree stopping at x²−2 over Q splits into two linear leaves over R. Compare the factorization of x⁴+4.'),
  ],
  eisenstein:[
    concept('eisensteinShift','content','Polinom primitif dan isi koefisien','Primitive polynomials and coefficient content','Isi adalah gcd koefisien bulat; primitif berarti isi 1.','Content is the gcd of integer coefficients; primitive means content 1.','Pisahkan f=c(f)f₀ dengan f₀ primitif. Gauss menunjukkan produk polinom primitif tetap primitif, sehingga isi produk adalah hasil kali isi faktor.','Write f=c(f)f₀ with primitive f₀. Gauss shows primitive products remain primitive, so product content multiplies.','Polinom bukan nol berkoefisien bulat; ambil gcd positif. Untuk koefisien rasional, bersihkan penyebut terlebih dahulu.','Use a nonzero integer polynomial and positive gcd. Clear denominators first for rational coefficients.',String.raw`f=\operatorname{cont}(f)f_0,\quad\operatorname{cont}(fg)=\operatorname{cont}(f)\operatorname{cont}(g)`,'Koefisien 6,9,3 mempunyai gcd 3; keluarkan faktor 3 untuk mendapat koefisien primitif 2,3,1.','Coefficients 6,9,3 have gcd 3; extracting 3 leaves primitive coefficients 2,3,1.'),
    concept('eisensteinShift','shift','Trik substitusi Eisenstein','The Eisenstein substitution trick','Polinom yang gagal tes langsung dapat lulus setelah menggeser variabel.','A polynomial failing the direct test may pass after shifting its variable.','Substitusi x→x+1 adalah automorfisma Q[x], sehingga faktorisasi dapat dipindah bolak-balik. Untuk x⁴+x³+x²+x+1, hasilnya x⁴+5x³+10x²+10x+5 yang memenuhi Eisenstein p=5.','Substitution x→x+1 is an automorphism of Q[x], transporting factorizations both ways. x⁴+x³+x²+x+1 becomes x⁴+5x³+10x²+10x+5, satisfying Eisenstein at p=5.','Cek semua syarat: p tidak membagi koefisien utama, membagi yang lain, dan p² tidak membagi konstanta. Tes cukup, bukan perlu.','Check all conditions: p misses the leading coefficient, divides the others, and p² misses the constant. The test is sufficient, not necessary.',String.raw`f(x+1)=x^4+5x^3+10x^2+10x+5`,'Dua baris koefisien menunjukkan sebelum dan sesudah substitusi. Baris kedua memperlihatkan pola pembagian oleh 5.','Two coefficient rows show before and after substitution. The second reveals the divisibility pattern for 5.'),
  ],
}
